"""Generate the explanatory C4 companion from existing numerical artifacts."""
from pathlib import Path
import json,csv
P=Path(__file__).resolve().parent

def main():
    r=json.loads((P/'results.json').read_text(encoding='utf-8')); d=json.loads((P/'decomposition.json').read_text(encoding='utf-8'))
    c1=json.loads((P.parent/'C1/results.json').read_text(encoding='utf-8')); c2=json.loads((P.parent/'C2/edge_selection.json').read_text(encoding='utf-8'))
    with (P/'degree_groups.csv').open(encoding='utf-8-sig',newline='') as f: groups=list(csv.DictReader(f))
    with (P/'degree_transitions.csv').open(encoding='utf-8-sig',newline='') as f: trans=list(csv.DictReader(f))
    models=r['models']; pct=lambda x:100*x
    def g(model,group):return next(x for x in groups if x['model']==model and int(x['bin'])==group)
    def transitions(model):
        rows=[x for x in trans if x['model']==model]
        return [sum(float(x['proportion']) for x in rows if cmp(int(x['to_bin']),int(x['from_bin']))) for cmp in [lambda a,b:a>b,lambda a,b:a==b,lambda a,b:a<b]]
    s=models['searle']; p=models['pic2word']; b=p['n10']['before']; a=p['n10']['after']; ps=g('pic2word',0);pt=transitions('pic2word');st=transitions('searle'); dec=d['point']; cp=c1['results']['pic2word']['comparison'][2]
    lines=['# C4 — Giải thích chi tiết kết quả centering','',
    'Tài liệu này giải thích [báo cáo C4 gốc](./bao_cao_C4.md) bằng lời và ví dụ. Số liệu được lấy từ [results.json](./results.json), [degree_groups.csv](./degree_groups.csv), [degree_transitions.csv](./degree_transitions.csv) và [decomposition.json](./decomposition.json). Đơn vị chênh lệch giữa hai tỷ lệ là **điểm phần trăm**.','',
    '## 1. C4 đang tìm câu trả lời gì?','',
    'C1 đặt câu hỏi centering có cải thiện tìm kiếm ở cùng chi phí hay không. C4 đi tiếp: **sau centering, không gian ảnh và đồ thị HNSW thay đổi thế nào, và thay đổi nào đi cùng việc HNSW bỏ sót ít hơn?** C4 đưa ra mô tả và bằng chứng phù hợp với một số cách giải thích; nó không tự chứng minh nguyên nhân.','',
    f"Trong cấu hình C4, Pic2Word có miss rate gốc **{pct(p['overall_miss']['before']):.2f}%**, sau centering **{pct(p['overall_miss']['after']):.2f}%**, tức giảm **{pct(p['overall_miss']['before']-p['overall_miss']['after']):.2f} điểm phần trăm**. SEARLE giảm từ **{pct(s['overall_miss']['before']):.2f}%** xuống **{pct(s['overall_miss']['after']):.2f}%**. Đây là so sánh tại cùng `efSearch=128`; chi phí `ndis` có thể khác nhau.", '',
    f"C1 có phép so sánh riêng tại cùng chi phí: ở khoảng **{cp['ndis_per_query']:.0f} ndis/query**, Pic2Word tăng retention từ **{pct(cp['original_retention']):.2f}%** lên **{pct(cp['centered_retention']):.2f}%**. Hai con số này trả lời câu hỏi khác với mức giảm miss tại cùng `efSearch` ở trên. C2 chưa khớp mật độ trong ngưỡng 2%; với Pic2Word, mức original gần nhất vẫn lệch **{pct(c2['selection']['pic2word']['median_relative_deviation']):+.2f}%** số cạnh median so với centered. Vì vậy chưa thể loại trừ lời giải thích liên quan đến mật độ đồ thị. [Xem C1](../C1/bao_cao_C1.md), [C2](../C2/bao_cao_C2.md).",'',
    '## 2. Trước hết: C4 đo những gì?','',
    f"Mỗi model dùng **{r['metadata']['gallery_size']:,} ảnh gallery**, **{r['metadata']['num_queries']:,} query** và **{len(r['metadata']['seeds'])} seed** dựng HNSW. Với mỗi query, exact search tìm 10 ảnh có điểm inner product cao nhất; đó là **exact top-10**. HNSW tìm xấp xỉ và có thể bỏ sót một số ảnh trong danh sách này.", '',
    '- **Retention@10**: số ảnh trong exact top-10 mà HNSW tìm lại được, chia 10. Nếu tìm lại 9 ảnh thì retention là 90%.',
    '- **Miss rate**: phần còn thiếu so với exact top-10; trong ví dụ trên là 10%. Với cùng tập query và cách lấy trung bình ở đây, miss rate = 1 − retention. Đây không phải tỷ lệ bỏ sót nhãn đúng do con người gán, cũng không phải mAP.',
    '- **Centering gallery**: tính vector trung bình `μ` của gallery đã chuẩn hóa, rồi trừ `μ` khỏi từng vector gallery. Khi tìm bằng inner product, query CIR được giữ nguyên; không chuẩn hóa lại gallery đã trừ mean. Điều này trừ cùng một hằng số điểm cho tất cả ảnh với cùng query, nên thứ hạng exact CIR được giữ.','',
    'Mỗi dòng “neighbor occurrence” là một cặp query–ảnh trong exact top-10 ở một seed. Một ảnh có thể xuất hiện với nhiều query và lặp lại qua seed: số dòng trong bảng **không phải số ảnh độc lập**.','',
    '## 3. MCS và vector trung bình: không gian ảnh trông thế nào?','',
    '**Vector trung bình `μ`** là trung bình các vector ảnh trong gallery. **MCS** ở đây là cosine trung bình giữa hai ảnh gallery khác nhau: giá trị dương lớn hơn cho thấy các hướng vector nhìn chung giống nhau hơn. Nó là thống kê của toàn gallery, không đo trực tiếp lỗi HNSW của một query.','',
    '| Model | ‖μ‖ gốc | MCS gốc | ‖μ‖ sau centering | MCS sau centering |','|---|---:|---:|---:|---:|']
    for model in ['searle','pic2word']:
        x=models[model]['geometry'];lines.append(f"| {model} | {x['mean_norm_original']:.5f} | {x['mcs_original_unit_formula']:.5f} | {x['mean_norm_centered']:.2g} | {x['mcs_centered_cosine']:.5f} |")
    lines += ['', 'MCS gốc của Pic2Word cao hơn SEARLE, phù hợp với dự đoán đã đăng ký. Sau khi trừ mean, mean vector gần 0 là kết quả được mong đợi từ chính phép biến đổi; MCS cũng gần 0. Để tính **cosine** sau centering, phép đo chuẩn hóa một bản sao các vector đã centered. Bản sao này chỉ dùng đo MCS; chỉ mục HNSW/IP vẫn dùng vector centered không chuẩn hóa lại. Vì vậy không thể lấy MCS gần 0 làm bằng chứng độc lập rằng centering gây giảm miss.','',
    '## 4. N10 phía gallery: ảnh nào thường được các ảnh khác chọn?','',
    '**`N10_gallery(x)`** là số ảnh gallery khác có ảnh `x` trong 10 láng giềng exact gần nhất của chúng. Ví dụ, `N10_gallery(x)=25` nghĩa là `x` được 25 ảnh khác chọn vào top-10; bằng 0 nghĩa là không ảnh gallery nào chọn `x`. Khi đếm, ảnh đang làm query được loại theo ID để không tính chính nó. Tổng số lần chọn luôn bằng số ảnh nhân 10.','',
    'Đại lượng này khác **`N10_query`**, là số query CIR có ảnh `x` trong exact top-10. Một bên dùng ảnh gallery làm truy vấn, bên kia dùng query CIR; không thể đọc hai giá trị như cùng một số đo. Nó cũng khác **in-degree HNSW**, là số cạnh đồ thị đi vào một nút, giải thích ở phần sau.','',
    '| Model | Skewness N10 gốc | Skewness N10 centered | Tỷ lệ N10=0 gốc | Tỷ lệ N10=0 centered |','|---|---:|---:|---:|---:|']
    for model in ['searle','pic2word']:
        x=models[model]['n10']; bb=x['before'];aa=x['after'];lines.append(f"| {model} | {bb['skewness']:.3f} | {aa['skewness']:.3f} | {pct(bb['zero_ratio']):.2f}% | {pct(aa['zero_ratio']):.2f}% |")
    lines += ['',f"Với Pic2Word, số ảnh có `N10_gallery=0` giảm từ **{b['zero_count']:,}** xuống **{a['zero_count']:,}**; tỷ lệ giảm từ **{pct(b['zero_ratio']):.2f}%** xuống **{pct(a['zero_ratio']):.2f}%**. Trong khi đó skewness tăng từ **{b['skewness']:.3f}** lên **{a['skewness']:.3f}**. Hai quan sát không mâu thuẫn: tỷ lệ bằng 0 mô tả một điểm của phân phối; skewness phụ thuộc toàn bộ hình dạng và đuôi phân phối. Không thể chỉ dựa vào một trong hai để kết luận hubness nói chung tốt hơn hay xấu hơn.",'',
    'Khi tính N10 centered, **cả ảnh dùng làm query gallery và ảnh trong chỉ mục đều là vector đã centered**, không chuẩn hóa lại. Vì vậy đây là phép đo quan hệ giữa ảnh–ảnh sau biến đổi; nó có thể thay đổi dù exact ranking của query CIR giữ nguyên.','',
    '## 5. Bậc vào HNSW và sự chuyển nhóm','',
    '**In-degree** của một ảnh là số cạnh có hướng ở tầng 0 của đồ thị HNSW trỏ vào nút ảnh đó. Nó mô tả cấu trúc chỉ mục, không phải số lần ảnh được chọn bởi exact search. Bậc vào thấp có thể đi cùng miss rate cao hơn, nhưng một quan sát liên hệ không tự chứng minh rằng thêm cạnh sẽ cứu được ảnh.','',
    f"Với Pic2Word, bậc vào trung bình của các exact-neighbor occurrence tăng từ **{p['exact_neighbor_indegree']['before']['mean']:.2f}** lên **{p['exact_neighbor_indegree']['after']['mean']:.2f}**. Các ranh giới nhóm dùng chung trước/sau là **{p['degree_bins']}**; nhóm 0 có bậc vào từ {int(p['degree_bins'][0])} đến dưới {int(p['degree_bins'][1])}, nhóm 4 từ {int(p['degree_bins'][4])} đến {int(p['degree_bins'][5])}.",'',
    f"Trong toàn bộ occurrence Pic2Word ghép cặp trước/sau, **{pct(pt[0]):.2f}%** chuyển lên nhóm bậc vào cao hơn, **{pct(pt[1]):.2f}%** giữ nhóm và **{pct(pt[2]):.2f}%** chuyển xuống. Với SEARLE, các tỷ lệ tương ứng là **{pct(st[0]):.2f}%**, **{pct(st[1]):.2f}%**, **{pct(st[2]):.2f}%**. Đây là tỷ lệ theo occurrence gộp 5 seed, không phải tỷ lệ ảnh duy nhất; [bảng chuyển nhóm](./degree_transitions.csv) có từng ô và CI.",'',
    '### Cách đọc bảng miss theo nhóm','',
    f"Ví dụ Pic2Word nhóm 0: trước centering có **{int(ps['before_rows']):,}** occurrence trong nhóm, miss **{pct(float(ps['before_miss_rate'])):.2f}%**; sau centering có **{int(ps['after_rows']):,}** occurrence, miss **{pct(float(ps['after_miss_rate'])):.2f}%**. Hai tập này khác nhau vì một số occurrence chuyển nhóm. Mức giảm giữa hai tỷ lệ là mô tả nhóm trước/sau, không phải mức cải thiện của cùng các ảnh.",'',
    f"Để nhìn cùng tập hơn, xét riêng **{int(ps['same_group_rows']):,}** occurrence giữ nhóm 0 ở cả hai nhánh, thuộc **{int(ps['same_group_images']):,}** ảnh khác nhau và **{int(ps['same_group_queries']):,}** query. Với tập chọn lọc này, miss centered − original là **{pct(float(ps['same_group_delta_miss'])):+.2f} điểm phần trăm**, CI 95% **[{pct(float(ps['same_group_ci_low'])):+.2f}; {pct(float(ps['same_group_ci_high'])):+.2f}]**. Điều này cho thấy một mức giảm được quan sát trong tập giữ nhóm, nhưng không chứng minh bậc vào gây ra mức giảm: chính việc chọn tập giữ nhóm có thể tạo khác biệt.",'',
    'Các CI ở các nhóm khác nhau có thể chứa 0; cần đọc từng nhóm trong [bảng chi tiết](./degree_groups.csv), không khái quát kết luận nhóm 0 cho mọi nhóm. Các hình [Pic2Word](./c4_pic2word_miss.png) và [SEARLE](./c4_searle_miss.png) biểu diễn miss theo nhóm trước/sau; chúng không tự thể hiện thay đổi trên cùng tập occurrence.','',
    '## 6. Bảng phân rã giữa model có nghĩa gì?','',
    'Phần này hỏi một câu khác: trên **đồ thị original seed 42**, chênh lệch miss giữa Pic2Word và SEARLE được mô hình logistic mô tả thế nào khi thay phân phối các đặc trưng. Đặc trưng gồm rank, log của bậc vào, log của N10 gallery, cùng hai điểm tương đồng query `s1` và `s100`. Đây không phải phép phân rã tác động của centering.','',
    f"Chênh lệch quan sát Pic2Word − SEARLE là **{pct(dec['gap']):+.2f} điểm phần trăm**. Theo mô hình dùng hệ số SEARLE, phần theo đặc trưng là **{pct(dec['forward_explained']):+.2f}** và phần còn lại **{pct(dec['forward_unexplained']):+.2f} điểm**; hai phần cộng lại bằng chênh lệch quan sát. Phần theo đặc trưng có thể lớn hơn tổng chênh lệch vì phần còn lại âm. Đổi chiều tham chiếu sang hệ số Pic2Word cho **{pct(dec['reverse_explained']):+.2f}** và **{pct(dec['reverse_unexplained']):+.2f} điểm**; khác biệt hai chiều cho thấy kết quả phụ thuộc cách tham chiếu.",'',
    'Khi thay từng nhóm đặc trưng, thứ tự thay đổi cũng làm kết quả phân bổ khác nhau. Các hàng “lai” được ghép theo vị trí hàng/rank của hai model, có thể không đại diện cho một query thực tế. Do đó không đọc phần trăm phân rã như phần lỗi “do” một đặc trưng gây ra. Toàn bộ hai thứ tự, khoảng tin cậy và miền giá trị nằm trong [decomposition.json](./decomposition.json).','',
    '## 7. Có thể và chưa thể kết luận gì?','',
    '**Có thể nói:** trên CIRCO và cấu hình này, Pic2Word có MCS gốc cao hơn; centering làm thay đổi phân phối N10 gallery và bậc vào, đồng thời nhiều exact-neighbor occurrence chuyển lên nhóm bậc vào cao hơn. Miss tại cùng `efSearch` giảm; C1 cung cấp thêm bằng chứng tăng retention tại các mức `ndis` chung đã khảo sát.','',
    '**Chưa thể nói:** MCS cao hoặc bậc vào thay đổi là nguyên nhân đã được chứng minh của lợi ích; centering tốt hơn mọi cách tăng mật độ; hoặc kết quả chắc chắn đúng trên backbone/dataset/cấu hình khác. C2 chưa khớp mật độ theo ngưỡng định trước.','',
    'Bootstrap giữ ghép cặp query và seed, nhưng một ảnh xuất hiện ở nhiều query nên các quan sát không hoàn toàn độc lập; chưa có kiểm tra độ nhạy gom cụm theo ảnh trong kết quả này. Có 5 seed; các CI là theo từng nhóm, không điều chỉnh đồng thời cho nhiều so sánh. ID nguồn của 800 test feature rows chưa được xác minh độc lập từng hàng. Những giới hạn này cần được giữ khi dùng kết quả trong báo cáo luận văn.','',
    '## 8. Đọc tiếp từ đâu?','',
    '- [Báo cáo C4 gốc](./bao_cao_C4.md): bảng đầy đủ theo nhóm và phương pháp.',
    '- [Bảng chuyển nhóm](./degree_transitions.csv) và [bảng nhóm](./degree_groups.csv): số dòng, số query, số ảnh và CI.',
    '- [Kết quả tổng hợp](./results.json) và [manifest](./run_manifest.json): số liệu gốc và provenance.',
    '- Bước C5 sẽ kiểm tra query nào được lợi theo nhóm `s1`; đó là câu hỏi tiếp theo, chưa được trả lời bởi C4.']
    # Preserve the model-dependent decomposition as an audit appendix, not the main mechanism.
    start=lines.index('## 6. Bảng phân rã giữa model có nghĩa gì?')
    end=lines.index('## 7. Có thể và chưa thể kết luận gì?')
    del lines[start:end]
    i=lines.index('## 4. N10 phía gallery: ảnh nào thường được các ảnh khác chọn?')
    diff=p['geometry']['mcs_original_unit_formula']-s['geometry']['mcs_original_unit_formula']
    lines[i:i]=[f"**Phản biện giả thuyết nón:** hai MCS gốc đều gần 0,5 và lệch nhau **{diff:.5f}**. Cả hai backbone có độ tập trung hướng đáng kể theo thống kê này, trong khi lợi ích centering quan sát được khác nhau. Dự đoán thứ tự MCS được hỗ trợ, nhưng **một mình MCS chưa giải thích được sự khác biệt hiệu ứng centering**. Chỉ có hai backbone và chưa có kiểm định tách riêng ảnh hưởng MCS, nên không thể khẳng định chênh lệch {diff:.5f} chắc chắn không có ý nghĩa hình học, cũng không thể bác bỏ mọi vai trò của MCS. Không dùng 'bung nón' làm lời giải thích đã được xác nhận.",'']
    i=lines.index('## 5. Bậc vào HNSW và sự chuyển nhóm')
    lines[i:i]=['**Vì sao hai backbone có thể đổi N10 theo hai hướng?** Với hai ảnh gallery `x, y`, sau centering điểm IP là `(x−μ)·(y−μ) = x·y − x·μ − y·μ + ‖μ‖²`. Khi cố định ảnh query `y`, các hạng `−y·μ + ‖μ‖²` là hằng số, còn `−x·μ` thay đổi theo ảnh ứng viên `x`; vì thế thứ hạng ảnh–ảnh và N10 có thể đổi. MCS chỉ tóm tắt một trung bình toàn cục, không mô tả phân bố các hình chiếu `x·μ`, norm, khoảng cách giữa các điểm gần nhau hay topology. Những khác biệt đó là các ứng viên cần đo để giải thích vì sao SEARLE và Pic2Word có chiều thay đổi tỷ lệ N10=0 trái nhau; C4 chưa xác định được cơ chế quyết định.','', 'Tăng skewness và N10=0 của SEARLE là thay đổi phân phối quan sát được, chưa đủ để gọi không gian bị “méo” theo nghĩa chất lượng ngữ nghĩa suy giảm. Với Pic2Word, giảm N10=0 phía gallery không đồng nghĩa các nút cô lập trong HNSW được “cứu”, vì hai đại lượng đo hai cấu trúc khác nhau.','']
    i=lines.index('### Cách đọc bảng miss theo nhóm')
    n=r['metadata']['gallery_size']; before=sorted(round(v['mean']*n) for v in p['gallery_indegree']['before'])[2]; after=sorted(round(v['mean']*n) for v in p['gallery_indegree']['after'])[2]
    with (P.parent/'C1/sweep.csv').open(encoding='utf-8-sig',newline='') as f:
        sweep=[x for x in csv.DictReader(f) if x['model']=='pic2word' and int(x['efSearch'])==128 and x['variant'] in ('original_ip','centered_ip')]
    nd0=sum(float(x['ndis_per_query']) for x in sweep if x['variant']=='original_ip')/5; nd1=sum(float(x['ndis_per_query']) for x in sweep if x['variant']=='centered_ip')/5
    lines[i:i]=[f"**Mật độ đồ thị là yếu tố cần kiểm soát.** Trong các đồ thị R2 được dùng cho C4, median số cạnh có hướng tầng 0 của Pic2Word tăng từ **{before:,}** lên **{after:,}**, tức thêm **{after-before:,} cạnh** ({(after/before-1)*100:.1f}%). Ở nhóm 0, số occurrence giảm từ **{int(ps['before_rows']):,}** xuống **{int(ps['after_rows']):,}** ({(1-int(ps['after_rows'])/int(ps['before_rows']))*100:.1f}%); đây là thay đổi thành phần nhóm, không phải các nút bị xóa. Ở nhóm 4, số occurrence tăng từ **{int(g('pic2word',4)['before_rows']):,}** lên **{int(g('pic2word',4)['after_rows']):,}**.",'', f"Các đồ thị C1 được dựng riêng cho thấy tại `efSearch=128`, Pic2Word dùng trung bình **{nd0:.1f} ndis/query** ở original và **{nd1:.1f}** ở centered ({(nd1/nd0-1)*100:+.1f}%). Đây là phép đo từ C1, không phải số đo ndis trực tiếp trên checkpoint đồ thị R2 của C4. C4 không khớp mật độ hoặc ndis, nên mức giảm miss cùng efSearch không thể tách riêng lợi ích hình học khỏi thay đổi tài nguyên tìm kiếm.",'', 'Một giả thuyết cần kiểm tra là centering làm thay đổi quyết định giữ láng giềng khi HNSW xây đồ thị IP, dẫn tới nhiều cạnh hơn và phân bố bậc vào khác. Hiện chưa đo trực tiếp các quyết định của bộ lọc xây dựng; vì vậy chưa thể gọi đó là “lỗi”, khẳng định thuật toán chủ động thiên vị, hoặc gán toàn bộ mức giảm miss cho số cạnh tăng.','']
    i=lines.index('## 7. Có thể và chưa thể kết luận gì?')
    lines[i:i]=['**Đọc đúng CI nhóm 0:** khoảng tin cậy của tập giữ nhóm vừa chạm phía âm; đây là bằng chứng tại một nhóm được xét, với giới hạn do chọn nhóm và nhiều phép so sánh. Chưa thể xem kết quả này là bằng chứng xác định về một cơ chế dẫn đường độc lập với thay đổi chi phí.','']
    i=lines.index('## 8. Đọc tiếp từ đâu?')
    lines[i:i]=['## 8. Hướng xử lý tiếp theo','', 'C1 trả lời câu hỏi cùng chi phí tìm kiếm và vẫn cho thấy lợi thế Pic2Word trong các ngân sách đã khảo sát; C4 không xóa bỏ kết quả đó. Nhưng cùng ndis chưa tự kiểm soát số cạnh. C2 hiện chỉ tìm được mức M gần nhất, chưa đạt ngưỡng lệch median số cạnh 2% cho cả hai model, nên **chưa có kết luận tại cùng mật độ**. Cần thiết kế bổ sung để khớp số cạnh, đồng thời so retention ở miền ndis chung; ghi trước cách chọn cấu hình, chi phí dựng/bộ nhớ và sai lệch còn lại. Chỉ sau đối chứng đó mới đánh giá được mức lợi thế còn lại khi mật độ được kiểm soát gần hơn.','', 'Phép phân rã giữa hai model của seed 42 được giữ tại [decomposition.json](./decomposition.json) để truy vết và tham khảo mô tả. Do phụ thuộc mô hình, thứ tự thay biến, ghép hàng và một seed, nó không phải bằng chứng chính cho cơ chế HNSW hoặc tác động centering.','']
    lines[lines.index('## 8. Đọc tiếp từ đâu?')]='## 9. Đọc tiếp từ đâu?'
